// The output every later step reads (Skip?, Send Touch 1, Mark Sent,
// Heartbeat), exactly as this node produced it before the requests moved out.
const c = $('Check capture').first().json;
const t = $('Plan touch 1').first().json;
if (t.outcome) return [{ json: t.outcome }];
const r = $input.first().json;
const ok = r.statusCode >= 200 && r.statusCode < 300;
const sendRow = ok && Array.isArray(r.body) ? r.body[0] : null;
if (!sendRow) return [{ json: { skipped: true, reason: 'duplicate_capture', email: c.email, lead_id: t.lead_id } }];
return [{ json: { skipped: false, email: c.email, lead_id: t.lead_id, send_id: sendRow.id, subject: c.subject, bodyTxt: c.bodyTxt, artifact: c.artifact } }];

// Validate, dedupe, upsert lead, insert touch-1 send row. Touch 1 is transactional artifact
// delivery, sent immediately; touches 2-4 queue at L1 via the Nurture Scheduler.
//
// The checks and the copy stay in code; the lead lookup, the lead insert and
// the touch-1 insert run in the HTTP steps that follow, over the stored
// Supabase credential. This node used to make them itself with the
// service-role key written into its source (moved 2026-10-03). "Process
// Capture" still produces the output every later step reads.
