const FOOTER = "

---
CTRL by Mindmaker. You received this because you requested an artifact at ctrl.themindmaker.ai.
Unsubscribe: https://krishraja10101.app.n8n.cloud/webhook/ctrl-unsub?e={email}";
const b = $input.first().json.body || {};
const email = String(b.email || '').trim().toLowerCase();
const honeypot = String(b.website || '');
const valid = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) && honeypot === '';
if (!valid) return [{ json: { valid: false, email, skip: { skipped: true, reason: honeypot ? 'honeypot' : 'invalid_email', email } } }];

const artifact = String(b.artifact_name || 'CTRL starter kit').slice(0, 120);
const utm = { utm_source: b.utm_source || 'direct', utm_medium: b.utm_medium || 'organic', utm_campaign: b.utm_campaign || 'mm_ctrl_capture', utm_content: b.utm_content || null, utm_term: b.utm_term || null };
const subject = FRAME[1].subject.replace('{artifact_name}', artifact);
const bodyTxt = FRAME[1].body.replace('{artifact_name}', artifact) + FOOTER.replace('{email}', encodeURIComponent(email));
const leadRow = { email, full_name: b.full_name || null, source_type: 'capture', source_ref: utm.utm_campaign, source_url: b.page_url || null, primary_venture: 'mm_ctrl', status: 'new', owner: 'system', assignee_agent: 'cleo', raw_extraction: { capture: true, artifact, ...utm } };
return [{ json: { valid: true, email, artifact, subject, bodyTxt, leadRow } }];

// Decides from the lookup: skip, use the lead found, or create one. The
// insert always runs; with nothing to create it sends an empty list, which
// writes nothing.
const c = $('Check capture').first().json;
const r = $input.first().json;
const found = Array.isArray(r.body) ? r.body : [];
const lead = c.valid && found.length > 0 ? found[0] : null;
let outcome = null;
if (!c.valid) outcome = c.skip;
else if (lead && lead.churned_at) outcome = { skipped: true, reason: 'suppressed', email: c.email };
const create = !outcome && !lead;
return [{ json: { outcome, lead, create, rows: create ? [c.leadRow] : [] } }];

// Builds the touch-1 send row. The unique constraint on acquisition_sends is
// the idempotency backstop: a repeat capture is refused by the insert, and
// "Process Capture" reports it as duplicate_capture.
const c = $('Check capture').first().json;
const p = $('Plan lead').first().json;
const r = $input.first().json;
let lead = p.lead;
if (p.create) {
  lead = (Array.isArray(r.body) ? r.body : [])[0] || null;
  if (!lead) throw new Error('lead insert returned no row');
}
const rows = !p.outcome && lead ? [{ lead_id: lead.id, lane: 'mm_ctrl', touch_number: 1, rendered_subject: c.subject, rendered_body: c.bodyTxt, status: 'approved' }] : [];
return [{ json: { outcome: p.outcome, lead_id: lead ? lead.id : null, rows } }];
